svg.desc:
\begin{gathered}
\begin{aligned}
& u_n = [u_{K+1}, u_{K+2}, \ldots, u_M] \\
& u_a \perp a(\theta) \quad \left(a \in \{K+1, K+2, \ldots, M\}\right) \\
& u_a^H a(\theta) = 0 \\[1ex]
& a(\theta)^H u_n u_n^H a(\theta) = \left\lVert u_n^H a(\theta) \right\rVert^2 = 0
\end{aligned}
\\[3ex]
P_{MUSIC,1D}(\theta) = \frac{1}{a(\theta)^H u_n u_n^H a(\theta)}
\qquad\qquad
P_{MUSIC,2D}(\theta, \varphi) = \frac{1}{a(\theta, \varphi)^H u_n u_n^H a(\theta, \varphi)}
\end{gathered}
